script:
carrier_event = {
	id = utopia.180
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		FROM = {
			OR = {
				has_valid_civic = civic_fanatic_purifiers
				#has_active_tradition = tr_purity_natural_order
			}
		}
		exists = fromfrom #crisis.202 can remove the last pop
		FROMFROM = {
			is_robot_pop_group = no
			NOT = {
				is_same_species = owner_species
			}
		}
		is_controlled_by = FROM
	}

	immediate = {
		from = {
			if = {
				limit = {
					has_origin = origin_nomadic_purger
					exists = overlord
				}
				while = {
					count = root.value:per_100_local_pop_amount
					overlord = {
						add_monthly_resource_mult = {
							resource = unity
							value = 1.5
							min = 5
							max = 100
						}
					}
				}
			}
			else = {
				while = {
					count = root.value:per_100_local_pop_amount
					add_monthly_resource_mult = {
						resource = unity
						value = 1.5
						min = 5
						max = 100
					}
				}
			}
		}
	}
}

