script:
carrier_event = {
	id = utopia.181
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		FROM = {
			has_valid_civic = civic_hive_devouring_swarm
		}
		exists = fromfrom #crisis.202 can remove the last pop
		FROMFROM = {
			is_robot_pop_group = no
			NOT = {
				is_same_species = owner_species
			}
		}
		is_controlled_by = FROM
	}

	immediate = {
		if = {
			limit = {
				from = {
					has_origin = origin_nomadic_purger
					exists = overlord
				}
			}
			while = {
				count = value:per_100_local_pop_amount
				from.overlord = {
					add_monthly_resource_mult = {
						resource = society_research
						value = 1
						min = 1
						max = 100
					}
				}
			}
		}
		else = {
			while = {
				count = value:per_100_local_pop_amount
				FROM = {
					add_monthly_resource_mult = {
						resource = society_research
						value = 1
						min = 1
						max = 100
					}
				}
			}
		}
		if = {
			limit = {
				owner = { is_wilderness_empire = yes }
			}
			set_variable = {
				which = biomass_amount
				value = local_pop_amount
			}
			multiply_variable = {
				which = biomass_amount
				value = 0.1
			}
			create_pop_group = {
				species = owner.species
				size = biomass_amount
			}
		}
		# grant timed modifiers from cyber hive
		if = {
			limit = {
				owner = {
					has_tradition = tr_cybernetics_finish
				}
			}
			owner = {
				add_modifier = { modifier = cyber_hive_node_booster days = 90 }
			}
			add_modifier = { modifier = cyber_hive_planet_booster days = 90 }
		}
	}
}

