				change_species = event_target:new_species
			}
			update_leader_after_modification = yes
		}
		every_owned_leader = {
			limit = {
				OR = {
					is_exact_same_species = event_target:new_species
					is_exact_same_species = event_target:old_species
				}
			}
			if = {
				limit = {
					is_exact_same_species = event_target:old_species
				}
