country_event = {
	id = utopia.2665
	hide_window = yes

	is_triggered_only = yes

	trigger = {
		OR = {
			has_country_flag = composer_covenant_confirmed
			has_country_flag = eater_covenant_confirmed
			has_country_flag = instrument_covenant_confirmed
			has_country_flag = whisperers_covenant_confirmed
		}
		OR = {
			check_variable = {
				which = composer_covenant_rank
				value < 90
			}
			check_variable = {
				which = eater_covenant_rank
				value < 90
			}
			check_variable = {
				which = instrument_covenant_rank
				value < 90
			}
			check_variable = {
				which = whisperers_covenant_rank
				value < 90
			}
		}
	}

	immediate = {
		if = { #Composer modifiers
			limit = {
				check_variable = {
					which = composer_covenant_rank
					value > 0
				}
			}
			change_variable = {
				which = composer_covenant_rank
				value = 0.03
			}
			if = { #Civics liked
				limit = {
					OR = {
						has_civic = civic_environmentalist
						is_catalytic_empire = yes
						has_civic = civic_idyllic_bloom
						is_toxic_baths_empire = yes
					}
				}
				change_variable = {
					which = composer_covenant_rank
					value = 0.04
				}
			}
			if = { #Civics disliked
				limit = {
					is_relentless_industrialist_empire = yes
					check_variable = {
						which = composer_covenant_rank
						value < 2
					}
				}
				change_variable = {
					which = composer_covenant_rank
					value = -0.02
				}
			}
			if = { #Ethics liked
				limit = {
					has_ethic = ethic_xenophile
				}
				change_variable = {
					which = composer_covenant_rank
					value = 0.03
				}
			}
			else_if = {
				limit = {
					is_fanatic_xenophile = yes
				}
				change_variable = {
					which = composer_covenant_rank
					value = 0.07
				}
			}
			if = { #Ethics disliked
				limit = {
					has_ethic = ethic_xenophobe
					check_variable = {
						which = composer_covenant_rank
						value < 2
					}
				}
				change_variable = {
					which = composer_covenant_rank
					value = -0.02
				}
			}
			else_if = {
				limit = {
					has_ethic = ethic_fanatic_xenophobe
					check_variable = {
						which = composer_covenant_rank
						value < 2
					}
				}
				change_variable = {
					which = composer_covenant_rank
					value = -0.05
				}
			}
			if = { #Tradition liked
				limit = {
					has_tradition = tr_adaptability_finish
				}
				change_variable = {
					which = composer_covenant_rank
					value = 0.06
				}
			}
			if = { #Acension Perks liked
				limit = {
					OR = {
						has_ascension_perk = ap_consecrated_worlds
						has_ascension_perk = ap_xeno_compatibility
					}
				}
				change_variable = {
					which = composer_covenant_rank
					value = 0.04
				}
			}
			if = { #Other things liked
				limit = {
					OR = {
						num_buildings = {
							type = building_medical_1
							value = 0
						}
						num_buildings = {
							type = building_medical_2
							value = 0
						}
						num_buildings = {
							type = building_medical_3
							value = 0
						}
					}
				}
				change_variable = {
					which = composer_covenant_rank
					value = 0.11
				}
			}
		}
		else_if = {		#Eater modifiers
			limit = {
				check_variable = {
					which = eater_covenant_rank
					value > 0
				}
			}
			change_variable = {
				which = eater_covenant_rank
				value = 0.03
			}
			if = { #Civics liked
				limit = {
					OR = {
						has_civic = civic_citizen_service
						has_civic = civic_fanatic_purifiers
						has_civic = civic_distinguished_admiralty
						has_civic = civic_naval_contractors
						has_civic = civic_barbaric_despoilers
						has_civic = civic_private_military_companies
					}
				}
				change_variable = {
					which = eater_covenant_rank
					value = 0.04
